tasks=[
{"slug":"29-longest-valid-parentheses","title":"Longest Valid Parentheses","difficulty":"Hard","subtopic":"Parsing","method":"longestValidParentheses","params":[("s","String")],"ret":"int","desc":"Given a string containing only `(` and `)`, return the length of its longest contiguous substring that forms a valid parenthesis sequence. Input: `s`. Output: the maximum valid substring length.","cons":["0 <= s.length <= 100000","s contains only '(' and ')'"],"time":"O(n)","space":"O(n)","py":"        stack = [-1]\n        best = 0\n        for i, c in enumerate(s):\n            if c == '(': stack.append(i)\n            else:\n                stack.pop()\n                if not stack: stack.append(i)\n                else: best = max(best, i - stack[-1])\n        return best","java":"        int[] stack = new int[s.length() + 1]; int size = 1; stack[0] = -1; int best = 0;\n        for (int i = 0; i < s.length(); i++) { if (s.charAt(i) == '(') stack[size++] = i; else { size--; if (size == 0) stack[size++] = i; else best = Math.max(best, i - stack[size - 1]); } }\n        return best;","examples":[({"s":"(()"},2),({"s":")()())"},4)],"tests":[{"s":""},{"s":"("},{"s":"()"},{"s":"((()))"},{"s":"()(()"},{"s":"()(())"},{"s":"))))(("},{"s":"(()())"},{"s":"()()()"}]},
{"slug":"30-isomorphic-strings","title":"Isomorphic Strings","difficulty":"Easy","subtopic":"String Matching","method":"isIsomorphic","params":[("s","String"),("t","String")],"ret":"boolean","desc":"Two strings are isomorphic when each character in the first can be consistently replaced by a character in the second, with no two distinct characters mapping to the same character. The mapping preserves positions. Return whether `s` and `t` are isomorphic. Input: two ASCII strings. Output: true or false.","cons":["0 <= s.length, t.length <= 100000","s and t contain ASCII characters"],"time":"O(n)","space":"O(1) for the ASCII alphabet","py":"        if len(s) != len(t): return False\n        forward, backward = {}, {}\n        for a, b in zip(s, t):\n            if (a in forward and forward[a] != b) or (b in backward and backward[b] != a): return False\n            forward[a] = b; backward[b] = a\n        return True","java":"        if (s.length() != t.length()) return false;\n        Map<Character, Character> forward = new HashMap<>(), backward = new HashMap<>();\n        for (int i = 0; i < s.length(); i++) { char a = s.charAt(i), b = t.charAt(i); if ((forward.containsKey(a) && forward.get(a) != b) || (backward.containsKey(b) && backward.get(b) != a)) return false; forward.put(a, b); backward.put(b, a); }\n        return true;","examples":[({"s":"egg","t":"add"},True),({"s":"foo","t":"bar"},False)],"tests":[{"s":"paper","t":"title"},{"s":"ab","t":"aa"},{"s":"","t":""},{"s":"a","t":"b"},{"s":"badc","t":"baba"},{"s":"1231","t":"4564"},{"s":"aa","t":"bb"},{"s":"abca","t":"zbxz"},{"s":"abc","t":"ab"}]},
{"slug":"31-repeated-string-match","title":"Repeated String Match","difficulty":"Medium","subtopic":"String Matching","method":"repeatedStringMatch","params":[("a","String"),("b","String")],"ret":"int","desc":"Given non-empty strings `a` and `b`, repeat `a` the fewest number of times so that `b` appears as a contiguous substring of the repeated string. Return that repetition count, or -1 if no repetition can contain `b`. Input: `a`, `b`. Output: the minimum count or -1.","cons":["1 <= a.length, b.length <= 1000","a and b contain lowercase English letters"],"time":"O(|a| * |b|)","space":"O(|a| + |b|)","py":"        repeated = a\n        count = 1\n        while len(repeated) < len(b): repeated += a; count += 1\n        if b in repeated: return count\n        if b in repeated + a: return count + 1\n        return -1","java":"        StringBuilder repeated = new StringBuilder(a); int count = 1;\n        while (repeated.length() < b.length()) { repeated.append(a); count++; }\n        if (repeated.indexOf(b) >= 0) return count;\n        repeated.append(a); return repeated.indexOf(b) >= 0 ? count + 1 : -1;","examples":[({"a":"abcd","b":"cdabcdab"},3),({"a":"a","b":"aaab"},-1)],"tests":[{"a":"a","b":"a"},{"a":"abc","b":"cabcab"},{"a":"abc","b":"ac"},{"a":"ab","b":"bababa"},{"a":"xyz","b":"zxyzxy"},{"a":"abcd","b":"abcdabcd"},{"a":"a","b":"aaaaa"},{"a":"abc","b":"bca"},{"a":"abcd","b":"dabcda"}]},
{"slug":"32-reverse-string-in-blocks","title":"Reverse String in Blocks","difficulty":"Easy","subtopic":"Parsing","method":"reverseStr","params":[("s","String"),("k","int")],"ret":"String","desc":"Given a string `s` and positive integer `k`, process consecutive blocks of `2k` characters from left to right. In each block, reverse its first `k` characters and leave the next `k` unchanged. If fewer than `k` characters remain, reverse all of them. Input: `s`, `k`. Output: the transformed string.","cons":["1 <= s.length <= 100000","1 <= k <= s.length","s contains lowercase English letters"],"time":"O(n)","space":"O(n)","py":"        chars = list(s)\n        for start in range(0, len(chars), 2 * k): chars[start:start + k] = reversed(chars[start:start + k])\n        return ''.join(chars)","java":"        char[] chars = s.toCharArray();\n        for (int start = 0; start < chars.length; start += 2 * k) { int left = start, right = Math.min(start + k, chars.length) - 1; while (left < right) { char c = chars[left]; chars[left++] = chars[right]; chars[right--] = c; } }\n        return new String(chars);","examples":[({"s":"abcdefg","k":2},"bacdfeg"),({"s":"abcd","k":2},"bacd")],"tests":[{"s":"a","k":1},{"s":"abcdef","k":3},{"s":"abcdefghij","k":3},{"s":"abcdefgh","k":1},{"s":"aabbcc","k":2},{"s":"zyxwvuts","k":4},{"s":"coding","k":5},{"s":"abcdefghijk","k":2},{"s":"mississippi","k":3}]},
{"slug":"33-roman-numeral-to-integer","title":"Roman Numeral to Integer","difficulty":"Easy","subtopic":"Parsing","method":"romanToInt","params":[("s","String")],"ret":"int","desc":"Convert a valid Roman numeral to its integer value. The symbols are `I`, `V`, `X`, `L`, `C`, `D`, and `M`; subtract a symbol when it is smaller than the symbol immediately following it, and otherwise add it. Input: a canonical Roman numeral from 1 through 3999. Output: its integer value.","cons":["1 <= s.length <= 15","s is a canonical Roman numeral representing an integer from 1 through 3999"],"time":"O(n)","space":"O(1)","py":"        value = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}\n        total = 0\n        for i, c in enumerate(s): total += -value[c] if i + 1 < len(s) and value[c] < value[s[i + 1]] else value[c]\n        return total","java":"        int total = 0;\n        for (int i = 0; i < s.length(); i++) { int x = value(s.charAt(i)); total += i + 1 < s.length() && x < value(s.charAt(i + 1)) ? -x : x; }\n        return total;\n    }\n    private int value(char c) { switch (c) { case 'I': return 1; case 'V': return 5; case 'X': return 10; case 'L': return 50; case 'C': return 100; case 'D': return 500; default: return 1000; }","examples":[({"s":"III"},3),({"s":"MCMXCIV"},1994)],"tests":[{"s":"IV"},{"s":"IX"},{"s":"LVIII"},{"s":"CDXLIV"},{"s":"MMXXVI"},{"s":"CM"},{"s":"XL"},{"s":"DCCVII"},{"s":"MMMCMXCIX"}]},
{"slug":"34-integer-to-roman-numeral","title":"Integer to Roman Numeral","difficulty":"Medium","subtopic":"Parsing","method":"intToRoman","params":[("num","int")],"ret":"String","desc":"Convert an integer from 1 through 3999 to its canonical Roman numeral representation. Use subtractive forms such as `IV`, `IX`, `XL`, `XC`, `CD`, and `CM` where needed. Input: integer `num`. Output: its Roman numeral string.","cons":["1 <= num <= 3999"],"time":"O(1)","space":"O(1)","py":"        values = [1000,900,500,400,100,90,50,40,10,9,5,4,1]\n        symbols = ['M','CM','D','CD','C','XC','L','XL','X','IX','V','IV','I']\n        out = []\n        for value, symbol in zip(values, symbols):\n            count, num = divmod(num, value)\n            out.append(symbol * count)\n        return ''.join(out)","java":"        int[] values = {1000,900,500,400,100,90,50,40,10,9,5,4,1}; String[] symbols = {\"M\",\"CM\",\"D\",\"CD\",\"C\",\"XC\",\"L\",\"XL\",\"X\",\"IX\",\"V\",\"IV\",\"I\"};\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < values.length; i++) while (num >= values[i]) { out.append(symbols[i]); num -= values[i]; }\n        return out.toString();","examples":[({"num":58},"LVIII"),({"num":1994},"MCMXCIV")],"tests":[{"num":1},{"num":4},{"num":9},{"num":40},{"num":90},{"num":400},{"num":944},{"num":2026},{"num":3999}]},
{"slug":"35-remove-duplicate-letters","title":"Remove Duplicate Letters","difficulty":"Medium","subtopic":"String Matching","method":"removeDuplicateLetters","params":[("s","String")],"ret":"String","desc":"Given a lowercase string `s`, remove repeated occurrences so every distinct letter appears exactly once. Among all valid results, return the lexicographically smallest string. Input: `s`. Output: the smallest valid result.","cons":["1 <= s.length <= 100000","s contains lowercase English letters"],"time":"O(n)","space":"O(1) for the alphabet","py":"        last = {c:i for i,c in enumerate(s)}\n        stack = []\n        used = set()\n        for i, c in enumerate(s):\n            if c in used: continue\n            while stack and stack[-1] > c and last[stack[-1]] > i: used.remove(stack.pop())\n            stack.append(c); used.add(c)\n        return ''.join(stack)","java":"        int[] last = new int[26]; for (int i = 0; i < s.length(); i++) last[s.charAt(i)-'a'] = i;\n        boolean[] used = new boolean[26]; char[] stack = new char[26]; int size = 0;\n        for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); int x = c-'a'; if (used[x]) continue; while (size > 0 && stack[size-1] > c && last[stack[size-1]-'a'] > i) used[stack[--size]-'a'] = false; stack[size++] = c; used[x] = true; }\n        return new String(stack, 0, size);","examples":[({"s":"bcabc"},"abc"),({"s":"cbacdcbc"},"acdb")],"tests":[{"s":"aaaa"},{"s":"abc"},{"s":"ecbacba"},{"s":"leetcode"},{"s":"bbcaac"},{"s":"abacb"},{"s":"zxyxyz"},{"s":"cdadabcc"},{"s":"a"}]},
{"slug":"36-reorganize-string-deterministically","title":"Reorganize String Deterministically","difficulty":"Medium","subtopic":"Parsing","method":"reorganizeString","params":[("s","String")],"ret":"String","desc":"Rearrange the lowercase letters of `s` so no equal characters are adjacent. Repeatedly choose, among characters different from the previous output character, the one with the greatest remaining count; break ties by choosing the alphabetically smallest character. Return the resulting string, or an empty string if no valid arrangement exists. Input: `s`. Output: the deterministic arrangement or empty string.","cons":["1 <= s.length <= 10000","s contains lowercase English letters"],"time":"O(n log 26)","space":"O(26)","py":"        counts = Counter(s)\n        out = []\n        previous = ''\n        while len(out) < len(s):\n            choices = [c for c in counts if counts[c] and c != previous]\n            if not choices: return ''\n            c = min(choices, key=lambda x: (-counts[x], x))\n            out.append(c); counts[c] -= 1; previous = c\n        return ''.join(out)","java":"        int[] count = new int[26]; for (char c : s.toCharArray()) count[c-'a']++;\n        StringBuilder out = new StringBuilder(); char previous = 0;\n        while (out.length() < s.length()) { int pick = -1; for (int c = 0; c < 26; c++) if (count[c] > 0 && 'a'+c != previous && (pick < 0 || count[c] > count[pick])) pick = c; if (pick < 0) return \"\"; previous = (char)('a'+pick); out.append(previous); count[pick]--; }\n        return out.toString();","examples":[({"s":"aab"},"aba"),({"s":"aaab"},"")],"tests":[{"s":"a"},{"s":"ab"},{"s":"aa"},{"s":"aabb"},{"s":"vvvlo"},{"s":"aaaaab"},{"s":"abcabc"},{"s":"zzzyx"},{"s":"aabbcc"}]},
{"slug":"37-longest-uncommon-subsequence-length","title":"Longest Uncommon Subsequence Length","difficulty":"Easy","subtopic":"Substrings","method":"findLUSlength","params":[("a","String"),("b","String")],"ret":"int","desc":"A string is an uncommon subsequence of two strings if it is a subsequence of one but not the other. Given strings `a` and `b`, return the length of the longest uncommon subsequence, or -1 if no such subsequence exists. Input: `a` and `b`. Output: the length or -1.","cons":["1 <= a.length, b.length <= 100","a and b contain lowercase English letters"],"time":"O(n+m)","space":"O(1)","py":"        return -1 if a == b else max(len(a), len(b))","java":"        return a.equals(b) ? -1 : Math.max(a.length(), b.length());","examples":[({"a":"aba","b":"cdc"},3),({"a":"aaa","b":"aaa"},-1)],"tests":[{"a":"a","b":"b"},{"a":"abcd","b":"abc"},{"a":"abc","b":"abc"},{"a":"x","b":"longer"},{"a":"aba","b":"bab"},{"a":"same","b":"different"},{"a":"aab","b":"aac"},{"a":"zz","b":"z"},{"a":"unique","b":"unique"}]},
{"slug":"38-count-distinct-subsequences","title":"Count Distinct Subsequences","difficulty":"Hard","subtopic":"Substrings","method":"numDistinct","params":[("s","String"),("t","String")],"ret":"int","desc":"Given lowercase strings `s` and `t`, count the different ways to delete characters from `s` without changing the order of the remaining characters so that the result equals `t`. Return the count modulo 1,000,000,007. Input: `s`, `t`. Output: the number of index choices modulo the stated modulus.","cons":["0 <= t.length <= s.length <= 1000","s and t contain lowercase English letters"],"time":"O(|s|*|t|)","space":"O(|t|)","py":"        mod = 1000000007\n        dp = [0] * (len(t) + 1)\n        dp[0] = 1\n        for c in s:\n            for j in range(len(t) - 1, -1, -1):\n                if c == t[j]: dp[j + 1] = (dp[j + 1] + dp[j]) % mod\n        return dp[-1]","java":"        final int MOD = 1000000007; int[] dp = new int[t.length() + 1]; dp[0] = 1;\n        for (int i = 0; i < s.length(); i++) for (int j = t.length() - 1; j >= 0; j--) if (s.charAt(i) == t.charAt(j)) dp[j + 1] = (int)(((long)dp[j + 1] + dp[j]) % MOD);\n        return dp[t.length()];","examples":[({"s":"rabbbit","t":"rabbit"},3),({"s":"babgbag","t":"bag"},5)],"tests":[{"s":"a","t":"a"},{"s":"a","t":"b"},{"s":"aaaa","t":"aa"},{"s":"abc","t":""},{"s":"abc","t":"abc"},{"s":"abc","t":"abcd"},{"s":"banana","t":"ban"},{"s":"mississippi","t":"issi"},{"s":"abcdef","t":""}]},
{"slug":"39-minimum-deletions-for-balanced-ab-string","title":"Minimum Deletions for a Balanced A-B String","difficulty":"Medium","subtopic":"Parsing","method":"minimumDeletions","params":[("s","String")],"ret":"int","desc":"A string over `a` and `b` is balanced when it can be written as zero or more `a` characters followed by zero or more `b` characters. Return the minimum number of characters to delete from `s` to make it balanced. Input: a string `s` containing only `a` and `b`. Output: the minimum deletions.","cons":["1 <= s.length <= 100000","s contains only 'a' and 'b'"],"time":"O(n)","space":"O(1)","py":"        b_count = deletions = 0\n        for c in s:\n            if c == 'b': b_count += 1\n            else: deletions = min(deletions + 1, b_count)\n        return deletions","java":"        int bCount = 0, deletions = 0;\n        for (int i = 0; i < s.length(); i++) if (s.charAt(i) == 'b') bCount++; else deletions = Math.min(deletions + 1, bCount);\n        return deletions;","examples":[({"s":"aababbab"},2),({"s":"bbaaaa"},2)],"tests":[{"s":"a"},{"s":"b"},{"s":"aaaa"},{"s":"bbbb"},{"s":"ab"},{"s":"ba"},{"s":"abababab"},{"s":"bbaabbab"},{"s":"abbbaaa"}]},
{"slug":"40-longest-substring-with-at-most-two-distinct","title":"Longest Substring With At Most Two Distinct Characters","difficulty":"Medium","subtopic":"Substrings","method":"lengthOfLongestSubstringTwoDistinct","params":[("s","String")],"ret":"int","desc":"Given a string `s`, return the length of its longest contiguous substring containing at most two distinct characters. Input: an ASCII string `s`. Output: the maximum qualifying length, or 0 for an empty string.","cons":["0 <= s.length <= 100000","s contains ASCII characters"],"time":"O(n)","space":"O(1) for the ASCII alphabet","py":"        counts = {}\n        left = best = 0\n        for right, c in enumerate(s):\n            counts[c] = counts.get(c, 0) + 1\n            while len(counts) > 2:\n                x = s[left]; counts[x] -= 1\n                if counts[x] == 0: del counts[x]\n                left += 1\n            best = max(best, right - left + 1)\n        return best","java":"        Map<Character, Integer> counts = new HashMap<>(); int left = 0, best = 0;\n        for (int right = 0; right < s.length(); right++) { char c = s.charAt(right); counts.put(c, counts.getOrDefault(c, 0) + 1); while (counts.size() > 2) { char x = s.charAt(left++); int n = counts.get(x) - 1; if (n == 0) counts.remove(x); else counts.put(x, n); } best = Math.max(best, right - left + 1); }\n        return best;","examples":[({"s":"eceba"},3),({"s":"ccaabbb"},5)],"tests":[{"s":""},{"s":"a"},{"s":"abc"},{"s":"aaaa"},{"s":"abababab"},{"s":"aabbcc"},{"s":"abaccc"},{"s":"xyzzzz"},{"s":"1231231"}]}
]

def py_type(t): return {"int":"int","boolean":"bool","String":"str"}[t]
root=ROOT/"problems"/"roster.json"; roster=json.loads(root.read_text())
for p in tasks:
    folder=BASE/p["slug"]; folder.mkdir()
    params=[{"name":n,"type":t} for n,t in p["params"]]
    meta={"title":p["title"],"difficulty":p["difficulty"],"subtopic":p["subtopic"],"companies":["Amazon","Google","Microsoft"],"description":p["desc"],"constraints":p["cons"],"hints":["Track only the character counts or prefixes needed to decide the next step.","Check repeated symbols, empty or minimal cases, and impossible arrangements."],"examples":[{"input":", ".join(f"{k} = {json.dumps(v)}" for k,v in x.items()),"output":str(y).lower() if isinstance(y,bool) else str(y)} for x,y in p["examples"]],"timeComplexity":p["time"],"spaceComplexity":p["space"],"compare":"exact","signature":{"kind":"function","method":p["method"],"params":params,"returns":p["ret"]}}
    (folder/"problem.json").write_text(json.dumps(meta,indent=2)+"\n")
    pyparams="".join(f", {n}: {py_type(t)}" for n,t in p["params"])
    (folder/"solution.py").write_text(f"class Solution:\n    def {p['method']}(self{pyparams}) -> {py_type(p['ret'])}:\n"+p["py"]+"\n")
    jparams=", ".join(f"{t} {n}" for n,t in p["params"])
    (folder/"Solution.java").write_text(f"class Solution {{\n    public {p['ret']} {p['method']}({jparams}) {{\n"+p["java"]+"\n    }\n}\n")
    cases=[x for x,_ in p["examples"]]+p["tests"]
    (folder/"tests.py").write_text("def visible():\n    return "+repr([{"in":x} for x in cases[:3]])+"\n\ndef hidden():\n    return "+repr([{"in":x} for x in cases[3:]])+"\n")
    roster.setdefault("strings",[]).append([p["slug"],p["title"],p["difficulty"],p["subtopic"],None])
root.write_text(json.dumps(roster,indent=2)+"\n")
print(f"Created {len(tasks)} string questions")
